-- DEV-002 V007 | integration + event/outbox
BEGIN;
CREATE TABLE church_integration.external_app(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES church_tenant.church(id),client_id text NOT NULL,name text NOT NULL,app_type text NOT NULL,status text NOT NULL,UNIQUE(tenant_id,client_id));
CREATE TABLE church_integration.integration_connection(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES church_tenant.church(id),app_id uuid NOT NULL REFERENCES church_integration.external_app(id),provider text NOT NULL,mode text NOT NULL,scopes jsonb NOT NULL DEFAULT '[]'::jsonb,status text NOT NULL,key_ref text);
CREATE TABLE church_integration.sso_realm(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES church_tenant.church(id),protocol text NOT NULL,issuer text NOT NULL,audience text,claim_mapping jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE church_integration.external_identity(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES church_tenant.church(id),provider text NOT NULL,subject text NOT NULL,person_id uuid NOT NULL REFERENCES church_identity.person(id),membership_id uuid REFERENCES church_community.church_membership(id),revoked_at timestamptz);
CREATE UNIQUE INDEX uq_external_identity_active ON church_integration.external_identity(tenant_id,provider,subject) WHERE revoked_at IS NULL;
CREATE TABLE church_integration.webhook_subscription(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES church_tenant.church(id),connection_id uuid NOT NULL REFERENCES church_integration.integration_connection(id),event_types jsonb NOT NULL,endpoint_ref text NOT NULL,secret_ref text NOT NULL,status text NOT NULL DEFAULT 'ACTIVE');
CREATE TABLE church_integration.idempotency_record(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES church_tenant.church(id),key text NOT NULL,request_hash text NOT NULL,response_ref text,expires_at timestamptz NOT NULL,UNIQUE(tenant_id,key));
CREATE TABLE church_integration.event_schema_registry(event_type text NOT NULL,version integer NOT NULL,json_schema jsonb NOT NULL,compatibility text NOT NULL,PRIMARY KEY(event_type,version));
CREATE TABLE church_integration.domain_event(event_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES church_tenant.church(id),aggregate_type text NOT NULL,aggregate_id text NOT NULL,event_type text NOT NULL,version integer NOT NULL,occurred_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE church_integration.outbox_event(event_id uuid PRIMARY KEY REFERENCES church_integration.domain_event(event_id),tenant_id uuid NOT NULL REFERENCES church_tenant.church(id),destination text NOT NULL,payload_json jsonb NOT NULL,payload_hash text NOT NULL,status text NOT NULL DEFAULT 'PENDING',attempts integer NOT NULL DEFAULT 0,next_attempt_at timestamptz);
CREATE TABLE church_integration.inbox_event(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),source text NOT NULL,external_event_id text NOT NULL,received_at timestamptz NOT NULL DEFAULT now(),processing_status text NOT NULL,UNIQUE(source,external_event_id));
CREATE TABLE church_integration.webhook_delivery(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),subscription_id uuid NOT NULL REFERENCES church_integration.webhook_subscription(id),event_id uuid NOT NULL REFERENCES church_integration.domain_event(event_id),attempt integer NOT NULL,response_code integer,next_retry_at timestamptz,UNIQUE(subscription_id,event_id,attempt));
CREATE TABLE church_integration.dead_letter(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),event_id uuid NOT NULL REFERENCES church_integration.domain_event(event_id),reason_code text NOT NULL,encrypted_debug_ref text);
COMMIT;
